    func testHMACAgainstPython() {
        for (a, k, m, expected) in hmacCases {
            XCTAssertEqual(hex(Hash.hmac(algo(a), key: bytes(k), message: bytes(m))), expected, "\(a) key=\(k.count / 2)B msg=\(m.count / 2)B")
        }
    }

    func testTOTPAgainstPython() {
        for (a, k, t, d, p, expected) in totpCases {
            let acct = OTPAccount(issuer: "x", name: "y", secret: bytes(k), algorithm: algo(a), digits: d, period: p)
            XCTAssertEqual(acct.code(at: Date(timeIntervalSince1970: t)), expected, "\(a) t=\(t)")
        }
    }
